/**
 * Cloudflare Worker entry: the OpenNext build handles requests, and a cron trigger resets the
 * shared demo data every day.
 */
import type { ExecutionContext, ScheduledController } from "@cloudflare/workers-types";
// @ts-expect-error -- generated by `opennextjs-cloudflare build`
import handler from "./.open-next/worker.js";
import { resetDemoDatabase } from "./src/server/demo/reset";

export default {
  fetch: (handler as ExportedHandler).fetch,
  async scheduled(_controller: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    ctx.waitUntil(resetDemoDatabase(env.DB).then((count) => console.log(`Demo reset: ${count} tables restored`)));
  },
};

type ExportedHandler = { fetch: (...args: unknown[]) => Promise<unknown> };
